// === Tab: mySketch ===
/**
 * CHAOS_FABRIC // CLIFFORD_ATTRACTOR
 * Trend: Complexity Science & Mathematical Beauty.
 * * CONCEPT:
 * Visualizing the hidden geometry of Chaos Theory.
 * Millions of particles trace the "Clifford Attractor" equation,
 * creating a ghostly, silk-like digital fabric.
 * * CONTROLS:
 * - MOUSE MOVE: Mutate the equation constants (a, b, c, d).
 * - CLICK: Clear canvas / Reset exposure.
 */

let points = [];
let numPoints = 10000; // Nombre de traceurs par frame
// Paramètres de l'attracteur (sensibles)
let a = 1.5, b = -1.8, c = 1.6, d = 0.9;
let baseHue;

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(0);
  colorMode(HSB, 360, 100, 100, 100);
  noSmooth();
  strokeWeight(0.5); // Trait ultra-fin pour effet "Soie"

  baseHue = random(360);

  // Initialisation des points aléatoires
  for (let i = 0; i < numPoints; i++) {
    points.push(createVector(random(width), random(height)));
  }
}

function draw() {
  // PAS DE BACKGROUND() !
  // C'est le secret : on garde les traces précédentes pour créer la densité.
  // On ajoute juste un voile noir presque invisible pour éviter la saturation totale à la longue
  if (frameCount % 600 === 0) {
      fill(0, 5);
      noStroke();
      rect(0,0,width,height);
  }

  // 1. INTERACTION (Mutation de l'équation)
  // La souris modifie subtilement 'a' et 'c'
  // On utilise lerp pour que la transition soit douce comme du liquide
  let targetA = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 1.0, 3.0);
  let targetC = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 0.5, 2.5);

  // Si on bouge la souris, on "floute" un peu l'image pour l'effet de mouvement
  if (dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), (window.simulatedPMouseX !== undefined ? window.simulatedPMouseX : (typeof sub_bass_prev !== 'undefined' ? map(sub_bass_prev, 0, 1, width*0.1, width*0.9) : (typeof window.simulatedMouseX !== 'undefined' ? window.simulatedMouseX - 12 : pmouseX))), (window.simulatedPMouseY !== undefined ? window.simulatedPMouseY : (typeof percussive_prev !== 'undefined' ? map(percussive_prev, 0, 1, height, 0) : (typeof window.simulatedMouseY !== 'undefined' ? window.simulatedMouseY - 12 : pmouseY)))) > 1) {
    fill(0, 20); // Efface légèrement plus vite quand on bouge
    noStroke();
    rect(0, 0, width, height);
    a = lerp(a, targetA, 0.05);
    c = lerp(c, targetC, 0.05);
  }

  // 2. RENDU DE L'ATTRACTEUR DE CLIFFORD
  translate(width / 2, height / 2);
  let scaleFactor = max(width, height) / 4;

  for (let i = 0; i < points.length; i++) {
    let p = points[i];

    // ÉQUATION MATHÉMATIQUE (Le Cœur du Chaos)
    // x' = sin(a*y) + c*cos(a*x)
    // y' = sin(b*x) + d*cos(b*y)

    // On normalise p.x et p.y pour le calcul (-2 à 2 environ)
    let nx = (p.x - width/2) / scaleFactor;
    let ny = (p.y - height/2) / scaleFactor;

    let newX = sin(a * ny) + c * cos(a * nx);
    let newY = sin(b * nx) + d * cos(b * ny);

    // Conversion vers coordonnées écran
    let screenX = newX * scaleFactor;
    let screenY = newY * scaleFactor;

    // Calcul de la couleur
    // La couleur dépend de la position et de la vitesse de changement
    let distCenter = dist(0, 0, screenX, screenY);
    let hueVal = (baseHue + map(distCenter, 0, width/2, 0, 100)) % 360;

    // Transparence très faible (2) pour l'effet "Vapeur"
    stroke(hueVal, 70, 100, 3);
    point(screenX, screenY);

    // Mise à jour de la position du point pour la prochaine itération
    // (On ne stocke pas newX/newY directement pour garder un aspect "nuage de points" 
    // plutôt qu'une ligne continue, on réinjecte de l'aléatoire parfois)

    if (random() < 0.5) {
        // Le point saute à sa nouvelle position calculée
        p.x = screenX + width/2;
        p.y = screenY + height/2;
    } else {
        // Le point redémarre ailleurs (évite que tous les points convergent vers un seul pixel)
        p.x = random(width);
        p.y = random(height);
    }
  }

  drawOverlay();
}

function drawOverlay() {
  resetMatrix();

  // HUD Mathématique
  fill(255);
  noStroke();
  textFont('Courier New');
  textSize(12);
  textAlign(LEFT, TOP);

  // Affichage des constantes en temps réel
  text("CLIFFORD_ATTRACTOR // EQUATION_SOLVER", 20, 20);
  text(`a = ${nf(a, 1, 3)}`, 20, 40);
  text(`b = ${nf(b, 1, 3)}`, 20, 55);
  text(`c = ${nf(c, 1, 3)}`, 20, 70);
  text(`d = ${nf(d, 1, 3)}`, 20, 85);

  let complexity = floor(frameCount / 10);
  text(`ITERATIONS: ${complexity}k`, width - 150, 20);
}

function mousePressed() {
  background(0); // Reset total
  baseHue = random(360); // Nouvelle ambiance couleur
  // Mutation aléatoire des paramètres b et d (moins influencés par la souris)
  b = random(-2, 2);
  d = random(-2, 2);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  background(0);
}

